import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { cleanup, render, screen, waitFor } from '@testing-library/react'
import { Provider } from 'react-redux'
import { configureStore } from '@reduxjs/toolkit'
import App from '@/App'
import settingsReducer, { defaultSettings } from '@/store/settingsSlice'
import tabsReducer from '@/store/tabsSlice'
import connectionReducer from '@/store/connectionSlice'
import sessionsReducer from '@/store/sessionsSlice'
import panesReducer from '@/store/panesSlice'
import tabRegistryReducer from '@/store/tabRegistrySlice'
import terminalMetaReducer from '@/store/terminalMetaSlice'
import extensionsReducer from '@/store/extensionsSlice'
import { networkReducer } from '@/store/networkSlice'
import {
  composeResolvedSettings,
  createDefaultServerSettings,
  resolveLocalSettings,
} from '@shared/settings'

const mockSend = vi.fn()
const mockOnMessage = vi.fn(() => () => {})
const mockOnReconnect = vi.fn(() => () => {})
const mockConnect = vi.fn().mockResolvedValue(undefined)
const mockApiGet = vi.fn().mockResolvedValue({})
const fetchSidebarSessionsSnapshot = vi.fn()
const wsState = {
  isReady: false,
  serverInstanceId: undefined as string | undefined,
}

vi.mock('@/lib/ws-client', () => ({
  getWsClient: () => ({
    send: mockSend,
    onMessage: mockOnMessage,
    onReconnect: mockOnReconnect,
    connect: mockConnect,
    setHelloExtensionProvider: vi.fn(),
    get isReady() {
      return wsState.isReady
    },
    get serverInstanceId() {
      return wsState.serverInstanceId
    },
    get state() {
      return wsState.isReady ? 'ready' : 'connected'
    },
  }),
}))

vi.mock('@/lib/api', () => ({
  api: {
    get: (url: string) => mockApiGet(url),
    patch: vi.fn().mockResolvedValue({}),
    post: vi.fn().mockResolvedValue({}),
  },
  fetchSidebarSessionsSnapshot: (options?: unknown) => fetchSidebarSessionsSnapshot(options),
  isApiUnauthorizedError: (err: any) => !!err && typeof err === 'object' && err.status === 401,
  isTransientRequestFailure: (err: any) =>
    !!err && (err.name === 'NetworkError' || err.name === 'AbortError' || [502, 503, 504].includes(err.status)),
}))

vi.mock('@/components/TabContent', () => ({
  default: () => <div data-testid="mock-tab-content">Tab Content</div>,
}))

vi.mock('@/components/Sidebar', () => ({
  default: () => <div data-testid="mock-sidebar">Sidebar</div>,
  AppView: {} as any,
}))

vi.mock('@/components/HistoryView', () => ({
  default: () => <div data-testid="mock-history-view">History View</div>,
}))

vi.mock('@/components/SettingsView', () => ({
  default: () => <div data-testid="mock-settings-view">Settings View</div>,
}))

vi.mock('@/components/OverviewView', () => ({
  default: () => <div data-testid="mock-overview-view">Overview View</div>,
}))

vi.mock('@/hooks/useTheme', () => ({
  useThemeEffect: () => {},
}))

vi.mock('@/components/SetupWizard', () => ({
  SetupWizard: () => <div data-testid="mock-setup-wizard">Setup Wizard</div>,
}))

function createStore() {
  const serverSettings = createDefaultServerSettings({
    loggingDebug: defaultSettings.logging.debug,
  })
  const localSettings = resolveLocalSettings()

  return configureStore({
    reducer: {
      settings: settingsReducer,
      tabs: tabsReducer,
      connection: connectionReducer,
      sessions: sessionsReducer,
      panes: panesReducer,
      tabRegistry: tabRegistryReducer,
      terminalMeta: terminalMetaReducer,
      network: networkReducer,
      extensions: extensionsReducer,
    },
    middleware: (getDefault) =>
      getDefault({
        serializableCheck: {
          ignoredPaths: ['sessions.expandedProjects'],
        },
      }),
    preloadedState: {
      settings: {
        serverSettings,
        localSettings,
        settings: composeResolvedSettings(serverSettings, localSettings),
        loaded: true,
        lastSavedAt: undefined,
      },
      tabs: {
        tabs: [{ id: 'tab-1', mode: 'shell' }],
        activeTabId: 'tab-1',
      },
      sessions: {
        projects: [],
        expandedProjects: new Set<string>(),
        wsSnapshotReceived: false,
        isLoading: false,
        error: null,
      },
      connection: {
        status: 'disconnected' as const,
        lastError: undefined,
        platform: null,
        availableClis: {},
        serverInstanceId: undefined,
      },
      panes: {
        layouts: {},
        activePane: {},
        paneTitles: {},
        paneTitleSetByUser: {},
        renameRequestTabId: null,
        renameRequestPaneId: null,
        zoomedPane: {},
      },
      tabRegistry: {
        deviceId: 'device-test',
        deviceLabel: 'device-test',
        deviceAliases: {},
        localOpen: [],
        remoteOpen: [],
        closed: [],
        localClosed: {},
        searchRangeDays: 30,
        loading: false,
      },
      terminalMeta: { byTerminalId: {} },
      network: {
        status: null,
        loading: false,
        configuring: false,
        error: null,
      },
      extensions: { entries: [] },
    },
  })
}

describe('auth required bootstrap flow (e2e)', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    localStorage.clear()
    fetchSidebarSessionsSnapshot.mockReset()
    fetchSidebarSessionsSnapshot.mockResolvedValue([])
    wsState.isReady = false
    wsState.serverInstanceId = undefined

    mockApiGet.mockImplementation((url: string) => {
      if (url === '/api/bootstrap') {
        return Promise.reject({ status: 401, message: 'Unauthorized' })
      }
      return Promise.resolve({})
    })
  })

  afterEach(() => {
    cleanup()
  })

  it('shows a friendly token URL recovery message after bootstrap 401', async () => {
    const store = createStore()

    render(
      <Provider store={store}>
        <App />
      </Provider>
    )

    await waitFor(() => {
      expect(screen.getByRole('dialog', { name: /authentication required/i })).toBeInTheDocument()
    })

    expect(screen.getByText(/Open Freshell using a token URL/i)).toBeInTheDocument()
    expect(screen.getByText(/\/\?token=[REDACTED]
    expect(screen.getByLabelText(/Token or token URL/i)).toBeInTheDocument()
    expect(mockConnect).not.toHaveBeenCalled()
  })

  it('shows the auth dialog immediately when no token is stored', async () => {
    mockApiGet.mockImplementation((url: string) => {
      if (url === '/api/bootstrap') {
        return new Promise(() => {})
      }
      return Promise.resolve({})
    })

    const store = createStore()

    render(
      <Provider store={store}>
        <App />
      </Provider>
    )

    await waitFor(() => {
      expect(screen.getByRole('dialog', { name: /authentication required/i })).toBeInTheDocument()
    })

    expect(mockConnect).not.toHaveBeenCalled()
  })
})

import { execFileSync } from 'node:child_process'
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import type { GlobalSetupContext } from 'vitest/node'
import { resolveNpmExecFileCommand } from './npm-command.js'

const __filename = fileURLToPath(import.meta.url)
const __dirname = path.dirname(__filename)
const PROJECT_ROOT = path.resolve(__dirname, '../..')

interface EnsureBuiltRuntimeDeps {
  execFileSync: typeof execFileSync
  rmSync: typeof fs.rmSync
  env: NodeJS.ProcessEnv
  platform: NodeJS.Platform
}

interface InstallBuiltRuntimeRefreshDeps {
  ensureBuiltRuntime: (projectRoot: string) => void
}

export function ensureBuiltRuntime(
  projectRoot: string,
  deps: EnsureBuiltRuntimeDeps = {
    execFileSync,
    rmSync: fs.rmSync,
    env: process.env,
    platform: process.platform,
  },
): void {
  deps.rmSync(path.join(projectRoot, 'dist', '.env'), { force: true })
  const npm = resolveNpmExecFileCommand(['run', 'build'], deps.env, deps.platform)
  deps.execFileSync(npm.command, npm.args, {
    cwd: projectRoot,
    env: {
      ...deps.env,
      NODE_ENV: 'production',
    },
    stdio: 'inherit',
  })
}

export function installBuiltRuntimeRefresh(
  project: Pick<GlobalSetupContext, 'onTestsRerun'>,
  projectRoot: string,
  deps: InstallBuiltRuntimeRefreshDeps = {
    ensureBuiltRuntime: (root) => ensureBuiltRuntime(root),
  },
): void {
  deps.ensureBuiltRuntime(projectRoot)
  project.onTestsRerun(() => {
    deps.ensureBuiltRuntime(projectRoot)
  })
}

export default async function globalSetup(project: GlobalSetupContext): Promise<void> {
  installBuiltRuntimeRefresh(project, PROJECT_ROOT)
}

import { execSync } from 'child_process'
import fs from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'

const __filename = fileURLToPath(import.meta.url)
const __dirname = path.dirname(__filename)

function findProjectRoot(): string {
  let dir = __dirname
  while (dir !== path.dirname(dir)) {
    if (fs.existsSync(path.join(dir, 'package.json'))) return dir
    dir = path.dirname(dir)
  }
  throw new Error('Could not find project root')
}

interface EnsureFreshE2eBuildDeps {
  execSync: typeof execSync
  env: NodeJS.ProcessEnv
  log: Pick<Console, 'log'>
}

export function ensureFreshE2eBuild(
  root: string,
  deps: EnsureFreshE2eBuildDeps = {
    execSync,
    env: process.env,
    log: console,
  },
): void {
  deps.log.log('[e2e-setup] Building client and server...')
  deps.execSync('npm run build:client && npm run build:server', {
    cwd: root,
    stdio: 'inherit',
    env: { ...deps.env, NODE_ENV: 'production' },
  })
  deps.log.log('[e2e-setup] Build complete.')
}

export default async function globalSetup() {
  const root = findProjectRoot()
  ensureFreshE2eBuild(root)
}

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react'
import { FreshAgentComposer } from '@/components/fresh-agent/FreshAgentComposer'
import type { FreshAgentSlashCommand } from '@shared/fresh-agent-slash-commands'

const apiGet = vi.fn()
vi.mock('@/lib/api', () => ({
  api: {
    get: (...args: unknown[]) => apiGet(...args),
    post: vi.fn(),
  },
}))

const COMMANDS: readonly FreshAgentSlashCommand[] = [
  { name: 'new', description: 'Start a new conversation in this pane', action: 'new' },
  { name: 'compact', description: 'Compact the context', action: 'compact' },
  { name: 'fork', description: 'Fork this conversation', action: 'fork', requiresCapability: 'fork' },
]

function getInput(): HTMLTextAreaElement {
  return screen.getByRole('textbox', { name: 'Chat message input' }) as HTMLTextAreaElement
}

describe('FreshAgentComposer', () => {
  beforeEach(() => {
    apiGet.mockReset()
    window.localStorage.clear()
    window.sessionStorage.clear()
  })
  afterEach(() => cleanup())

  it('opens the slash menu when typing / and runs the highlighted command', () => {
    const onCommand = vi.fn()
    render(<FreshAgentComposer commands={COMMANDS} onCommand={onCommand} />)

    fireEvent.change(getInput(), { target: { value: '/for' } })
    const menu = screen.getByRole('menu', { name: 'Slash commands' })
    expect(menu).toHaveTextContent('/fork')
    expect(menu).not.toHaveTextContent('/new')

    fireEvent.keyDown(getInput(), { key: 'Enter' })
    expect(onCommand).toHaveBeenCalledWith(
      expect.objectContaining({ name: 'fork' }),
      '',
    )
  })

  it('passes arguments through slash command text', () => {
    const onCommand = vi.fn()
    render(<FreshAgentComposer commands={COMMANDS} onCommand={onCommand} />)

    fireEvent.change(getInput(), { target: { value: '/compact focus on ws-handler' } })
    fireEvent.keyDown(getInput(), { key: 'Enter' })
    expect(onCommand).toHaveBeenCalledWith(
      expect.objectContaining({ name: 'compact' }),
      'focus on ws-handler',
    )
  })

  it('completes the highlighted slash command with Tab without sending it', () => {
    const onCommand = vi.fn()
    render(<FreshAgentComposer commands={COMMANDS} onCommand={onCommand} />)

    fireEvent.change(getInput(), { target: { value: '/for' } })
    fireEvent.keyDown(getInput(), { key: 'Tab' })

    expect(getInput().value).toBe('/fork ')
    expect(onCommand).not.toHaveBeenCalled()
  })

  it('completes @ mentions against the files API anchored at the session cwd', async () => {
    apiGet.mockResolvedValue({
      suggestions: [
        { path: '/home/dan/code/freshell/server', isDirectory: true },
        { path: '/home/dan/code/freshell/shared/settings.ts', isDirectory: false },
      ],
    })
    const onSend = vi.fn()
    render(<FreshAgentComposer commands={COMMANDS} onSend={onSend} cwd="/home/dan/code/freshell" />)

    fireEvent.change(getInput(), { target: { value: 'look at @s' } })

    await waitFor(() => {
      expect(apiGet).toHaveBeenCalledWith(
        `/api/files/complete?prefix=${encodeURIComponent('/home/dan/code/freshell/s')}`,
      )
    })
    const menu = await screen.findByRole('menu', { name: 'File suggestions' })
    expect(menu).toHaveTextContent('server')
    expect(menu).toHaveTextContent('shared/settings.ts')

    fireEvent.click(screen.getByRole('menuitem', { name: /shared\/settings\.ts/ }))
    expect(getInput().value).toBe('look at shared/settings.ts ')
  })

  it('descends into directories on selection and keeps completing', async () => {
    apiGet.mockResolvedValue({
      suggestions: [{ path: '/home/dan/code/freshell/server', isDirectory: true }],
    })
    render(<FreshAgentComposer commands={COMMANDS} cwd="/home/dan/code/freshell" />)

    fireEvent.change(getInput(), { target: { value: '@se' } })
    const item = await screen.findByRole('menuitem', { name: /server/ })
    fireEvent.click(item)

    expect(getInput().value).toBe('@server/')
    await waitFor(() => {
      expect(apiGet).toHaveBeenCalledWith(
        `/api/files/complete?prefix=${encodeURIComponent('/home/dan/code/freshell/server/')}`,
      )
    })
  })

  it('recalls prompt history with arrow keys from an empty input', () => {
    const onSend = vi.fn()
    render(
      <FreshAgentComposer
        commands={COMMANDS}
        onSend={onSend}
        historyKey="fresh-agent-prompt-history:test"
      />,
    )

    fireEvent.change(getInput(), { target: { value: 'first prompt' } })
    fireEvent.keyDown(getInput(), { key: 'Enter' })
    fireEvent.change(getInput(), { target: { value: 'second prompt' } })
    fireEvent.keyDown(getInput(), { key: 'Enter' })
    expect(onSend).toHaveBeenCalledTimes(2)
    expect(getInput().value).toBe('')

    fireEvent.keyDown(getInput(), { key: 'ArrowUp' })
    expect(getInput().value).toBe('second prompt')
    fireEvent.keyDown(getInput(), { key: 'ArrowUp' })
    expect(getInput().value).toBe('first prompt')
    fireEvent.keyDown(getInput(), { key: 'ArrowDown' })
    expect(getInput().value).toBe('second prompt')
    fireEvent.keyDown(getInput(), { key: 'ArrowDown' })
    expect(getInput().value).toBe('')
  })

  it('persists prompt history per history key', () => {
    const key = 'fresh-agent-prompt-history:persist-test'
    const first = render(
      <FreshAgentComposer commands={COMMANDS} onSend={vi.fn()} historyKey={key} />,
    )
    fireEvent.change(getInput(), { target: { value: 'remembered prompt' } })
    fireEvent.keyDown(getInput(), { key: 'Enter' })
    first.unmount()

    render(<FreshAgentComposer commands={COMMANDS} onSend={vi.fn()} historyKey={key} />)
    fireEvent.keyDown(getInput(), { key: 'ArrowUp' })
    expect(getInput().value).toBe('remembered prompt')
  })

  it('does not hijack ArrowUp while drafting text', () => {
    render(
      <FreshAgentComposer
        commands={COMMANDS}
        onSend={vi.fn()}
        historyKey="fresh-agent-prompt-history:drafting"
      />,
    )
    fireEvent.change(getInput(), { target: { value: 'sent already' } })
    fireEvent.keyDown(getInput(), { key: 'Enter' })

    fireEvent.change(getInput(), { target: { value: 'a draft in progress' } })
    fireEvent.keyDown(getInput(), { key: 'ArrowUp' })
    expect(getInput().value).toBe('a draft in progress')
  })

  it('focuses the chat input by default when requested and enabled', async () => {
    render(<FreshAgentComposer commands={COMMANDS} focusOnReady onSend={vi.fn()} />)

    await waitFor(() => {
      expect(document.activeElement).toBe(getInput())
    })
  })

  it('keeps the subtle thinking bar slot stable when work starts and stops', () => {
    const { rerender } = render(<FreshAgentComposer commands={COMMANDS} onSend={vi.fn()} />)

    expect(screen.getByTestId('fresh-agent-thinking-bar')).toHaveAttribute('data-state', 'idle')

    rerender(<FreshAgentComposer commands={COMMANDS} thinking onSend={vi.fn()} />)
    expect(screen.getByTestId('fresh-agent-thinking-bar')).toBeInTheDocument()
    expect(screen.getByTestId('fresh-agent-thinking-bar')).toHaveAttribute('data-state', 'active')
  })

  it('matches message text sizing and labels the command and send buttons with tooltips', () => {
    render(<FreshAgentComposer commands={COMMANDS} onSend={vi.fn()} />)

    expect(getInput().className).toContain('fresh-agent-composer-input')
    expect(getInput().className).toContain('text-base')
    expect(getInput().className).toContain('sm:text-sm')

    const commandButton = screen.getByRole('button', { name: 'Slash commands' })
    expect(commandButton).toHaveAttribute('title', 'Slash commands')
    expect(commandButton.querySelector('.lucide-list-start')).not.toBeNull()

    fireEvent.mouseEnter(commandButton)
    expect(screen.getByRole('tooltip')).toHaveTextContent('Slash commands')
    fireEvent.mouseLeave(commandButton)

    const sendButton = screen.getByRole('button', { name: 'Send' })
    expect(sendButton).toHaveAttribute('title', 'Send message')
    fireEvent.focus(sendButton)
    expect(screen.getByRole('tooltip')).toHaveTextContent('Send message')
  })

  it('shows queued message counts without pinning queued text above the composer', () => {
    const onCancelQueued = vi.fn()
    render(
      <FreshAgentComposer
        commands={COMMANDS}
        queuedMessages={[
          'Do not pin my newest message at the bottom',
          'Keep this queued follow-up private until expanded',
        ]}
        onCancelQueued={onCancelQueued}
      />,
    )

    const queuedStatus = screen.getByRole('status', { name: 'Queued messages' })
    expect(queuedStatus).toHaveTextContent('2 queued')
    expect(screen.queryByText('Do not pin my newest message at the bottom')).not.toBeInTheDocument()
    expect(screen.queryByText('Keep this queued follow-up private until expanded')).not.toBeInTheDocument()

    const removeButtons = screen.getAllByRole('button', { name: /Remove queued message/ })
    expect(removeButtons).toHaveLength(2)
    fireEvent.click(removeButtons[0])
    expect(onCancelQueued).toHaveBeenCalledWith(0)
  })

  describe('state-aware disabled behavior', () => {
    it('shows the provided placeholder instead of the generic read-only text', () => {
      render(
        <FreshAgentComposer
          commands={COMMANDS}
          disabled
          placeholder="Starting session…"
        />,
      )
      expect(getInput()).toHaveAttribute('placeholder', 'Starting session…')
    })

    it('falls back to Read-only session when disabled without a placeholder', () => {
      render(<FreshAgentComposer commands={COMMANDS} disabled />)
      expect(getInput()).toHaveAttribute('placeholder', 'Read-only session')
    })

    it('keeps /new reachable from the command menu while disabled', () => {
      const onCommand = vi.fn()
      render(<FreshAgentComposer commands={COMMANDS} disabled onCommand={onCommand} />)

      const browse = screen.getByRole('button', { name: 'Slash commands' })
      expect(browse).toBeEnabled()
      fireEvent.click(browse)
      fireEvent.click(screen.getByRole('menuitem', { name: /\/new/ }))
      expect(onCommand).toHaveBeenCalledWith(expect.objectContaining({ name: 'new' }), '')

      // Other commands stay blocked while disabled.
      fireEvent.click(browse)
      fireEvent.click(screen.getByRole('menuitem', { name: /\/compact/ }))
      expect(onCommand).toHaveBeenCalledTimes(1)
    })
  })
})

import path from 'node:path'

import { describe, expect, it, vi } from 'vitest'

import { ensureBuiltRuntime, installBuiltRuntimeRefresh } from '../../../setup/e2e-browser-global-setup.js'

describe('ensureBuiltRuntime', () => {
  it('rebuilds the compiled runtime before helper tests', () => {
    const execFileSync = vi.fn()
    const rmSync = vi.fn()

    ensureBuiltRuntime('/repo', {
      execFileSync,
      rmSync,
      env: { PATH: '/bin' },
      platform: 'linux',
    })

    expect(rmSync).toHaveBeenCalledWith(path.join('/repo', 'dist', '.env'), { force: true })
    expect(execFileSync).toHaveBeenCalledWith('npm', ['run', 'build'], {
      cwd: '/repo',
      env: {
        PATH: '/bin',
        NODE_ENV: 'production',
      },
      stdio: 'inherit',
    })
  })

  it('uses the npm CLI JavaScript entrypoint on Windows when npm exposes it', () => {
    const execFileSync = vi.fn()
    const rmSync = vi.fn()
    const npmExecPath = path.join('C:\\repo', 'node_modules', 'npm', 'bin', 'npm-cli.js')

    ensureBuiltRuntime('C:\\repo', {
      execFileSync,
      rmSync,
      env: {
        PATH: 'C:\\Windows\\System32',
        npm_execpath: npmExecPath,
      },
      platform: 'win32',
    })

    expect(rmSync).toHaveBeenCalledWith(path.join('C:\\repo', 'dist', '.env'), { force: true })
    expect(execFileSync).toHaveBeenCalledWith(process.execPath, [npmExecPath, 'run', 'build'], {
      cwd: 'C:\\repo',
      env: {
        PATH: 'C:\\Windows\\System32',
        npm_execpath: npmExecPath,
        NODE_ENV: 'production',
      },
      stdio: 'inherit',
    })
  })

  it('rebuilds the compiled runtime on every watch rerun', async () => {
    let rerunHandler: ((testFiles: unknown[]) => Promise<void> | void) | undefined
    const ensureBuiltRuntime = vi.fn()

    installBuiltRuntimeRefresh({
      onTestsRerun(handler) {
        rerunHandler = handler
      },
    }, '/repo', {
      ensureBuiltRuntime,
    })

    expect(ensureBuiltRuntime).toHaveBeenCalledTimes(1)
    expect(ensureBuiltRuntime).toHaveBeenNthCalledWith(1, '/repo')
    expect(rerunHandler).toBeTypeOf('function')

    await rerunHandler?.([])

    expect(ensureBuiltRuntime).toHaveBeenCalledTimes(2)
    expect(ensureBuiltRuntime).toHaveBeenNthCalledWith(2, '/repo')
  })
})

import { test, expect } from '../helpers/fixtures.js'

test.describe('Authentication', () => {
  test('shows auth modal when no token provided', async ({ page, serverInfo }) => {
    await page.goto(serverInfo.baseUrl)
    // Should show the auth modal
    const modal = page.getByRole('dialog')
    await expect(modal).toBeVisible({ timeout: 10_000 })
    // Should have a token input
    const input = page.getByPlaceholder(/token/i)
    await expect(input).toBeVisible()
  })

  test('shows auth modal with wrong token', async ({ page, serverInfo }) => {
    await page.goto(`${serverInfo.baseUrl}/?token=[REDACTED]
    const modal = page.getByRole('dialog')
    await expect(modal).toBeVisible({ timeout: 10_000 })
  })

  test('authenticates with correct token via URL', async ({ freshellPage, harness }) => {
    // freshellPage already has the correct token
    const status = await harness.getConnectionStatus()
    expect(status).toBe('ready')
  })

  test('authenticates via auth modal input', async ({ page, serverInfo, harness }) => {
    await page.goto(serverInfo.baseUrl)
    // Wait for the auth modal
    const input = page.getByPlaceholder(/token/i)
    await expect(input).toBeVisible({ timeout: 10_000 })

    // Type the correct token
    await input.fill(serverInfo.token)
    // Submit
    const submitButton = page.getByRole('button', { name: /connect|submit|go/i })
    await submitButton.click()

    // After auth, navigate with ?e2e=1 to activate the test harness
    // (the initial load was without e2e=1, so no harness)
    await page.goto(`${serverInfo.baseUrl}/?e2e=1`)
    await harness.waitForHarness()
    await harness.waitForConnection()

    // Verify connected
    const status = await harness.getConnectionStatus()
    expect(status).toBe('ready')
  })

  test('API rejects requests without auth header', async ({ serverInfo }) => {
    const res = await fetch(`${serverInfo.baseUrl}/api/settings`)
    expect(res.status).toBe(401)
  })

  test('health endpoint works without auth', async ({ serverInfo }) => {
    const res = await fetch(`${serverInfo.baseUrl}/api/health`)
    expect(res.status).toBe(200)
    const body = await res.json()
    expect(body.ok).toBe(true)
  })
})

import { describe, it, expect, vi, beforeEach } from 'vitest'
import {
  copyFreshAgentCodeBlock,
  copyFreshAgentToolInput,
  copyFreshAgentToolOutput,
  copyFreshAgentDiffNew,
